\mathsf{Der}^{\mathsf{Ty}}_{\mathsf M}
=
\left\{
D\in\mathsf{Tree}_{\mathsf M}(\mathsf{Jud}_{\mathsf M}):
\forall u\in\operatorname{nodes}(D)\ 
\bigl(
(\operatorname{childlabs}_D(u),\operatorname{lab}_D(u))
\in\mathsf{Rule}^{\mathsf M}_{\mathsf{Ty}}
\bigr)
\right\}.

\begin{aligned}
\mathsf{SubPresCert}_{\mathsf M}
=\{(&\Gamma,x,A,t,B,a,D_t,D_a,D_s):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\ x\in\mathsf{Var},\ A,B\in\mathsf{Ty}_{\mathsf M},\ t,a\in\mathsf{Tm}_{\mathsf M},\\
&x\notin\operatorname{dom}(\Gamma),\
D_t\in\mathsf{TyCert}_{\mathsf M}((\Gamma,x:A),t,B),\
D_a\in\mathsf{TyCert}_{\mathsf M}(\Gamma,a,A),\
D_s\in\mathsf{TyCert}_{\mathsf M}(\Gamma,t[x:=a],B)\}.
\end{aligned}

\mathsf{SubPres}_{\mathsf M}
\subseteq
\mathsf{Ctx}_{\mathsf M}
\times\mathsf{Var}
\times\mathsf{Ty}_{\mathsf M}
\times\mathsf{Tm}_{\mathsf M}
\times\mathsf{Ty}_{\mathsf M}
\times\mathsf{Tm}_{\mathsf M}

\begin{aligned}
\mathsf{BetaCert}_{\mathsf M}
=\{(&E,\kappa):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\ x\in\mathsf{Var},\ A,B\in\mathsf{Ty}_{\mathsf M},\ t,a\in\mathsf{Tm}_{\mathsf M},\\
&E=(\Gamma,(\lambda x.t)a,t[x:=a],B)\in\mathsf{EqJud}_{\mathsf M},\
\kappa\in\mathsf{SubPresCert}_{\mathsf M}(\Gamma,x,A,t,B,a)\},
\end{aligned}

\begin{aligned}
\mathsf{BindBetaCert}_{\mathsf M}
=\{(&E,\kappa):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\ x\in\mathsf{Var},\ A,B\in\mathsf{Ty}_{\mathsf M},\ n,t\in\mathsf{Tm}_{\mathsf M},\\
&E=(\Gamma,\operatorname{bind}(\eta(t),x,n),n[x:=t],T B)\in\mathsf{EqJud}_{\mathsf M},\
\kappa\in\mathsf{SubPresCert}_{\mathsf M}(\Gamma,x,A,n,T B,t)\}.
\end{aligned}
